impl<'a> Iterator for NonFused<'a> {
    type Item = i64;
    fn next(&mut self) -> Option<i64> {
        let call = *self.calls;
        *self.calls += 1usize;
        if call == 0usize {
            Some(7i64)
        } else if call == 1usize {
            None
        } else {
            Some(9i64)
        }
    }
}

{
    assert!("".chars().count() == 0usize);
    assert!("a\u{e9}\u{65e5}\u{1f980}".chars().count() == 4usize);
    let empty: Vec<String> = Vec::new();
    assert!(empty.into_iter().count() == 0usize);
    let words = vec!["first".to_string(), "second".to_string()];
    assert!(std::iter::count(words.into_iter()) == 2usize);
    let mut calls = 0usize;
    {
        let iterator = Observed { calls: &mut calls, index: 0usize, end: 3usize };
        assert!(iterator.count() == 3usize);
    }
    assert!(calls == 4usize);
    let mut empty_calls = 0usize;
    {
        let iterator = Observed { calls: &mut empty_calls, index: 0usize, end: 0usize };
        assert!(iterator.count() == 0usize);
    }
    assert!(empty_calls == 1usize);
    let characters: Vec<char> = "a\u{e9}\u{65e5}\u{1f980}".chars().collect();
    assert!(characters.len() == 4usize);
    assert!(characters[0usize] == 'a');
    assert!(characters[1usize] == '\u{e9}');
    assert!(characters[2usize] == '\u{65e5}');
    assert!(characters[3usize] == '\u{1f980}');
    let empty_characters: Vec<char> = "".chars().collect();
    assert!(empty_characters.is_empty());
    let mut collected_calls = 0usize;
    let numbers: Vec<i64>;
    {
        let iterator = Observed { calls: &mut collected_calls, index: 0usize, end: 3usize };
        numbers = std::iter::collect(iterator);
    }
    assert!(collected_calls == 4usize);
    assert!(numbers.len() == 3usize);
    assert!(numbers[0usize] == 0i64 && numbers[1usize] == 1i64 && numbers[2usize] == 2i64);
    let words: Vec<String> = vec!["first".to_string(), "second".to_string()].into_iter().collect();
    assert!(words.len() == 2usize);
    assert!(words[0usize].as_str() == "first" && words[1usize].as_str() == "second");
    assert!(std::iter::range_from(9usize).take(0usize).count() == 0usize);
    let numbers: Vec<usize> = std::iter::range_from(7usize).take(4usize).collect();
    assert!(numbers.len() == 4usize);
    assert!(numbers[0usize] == 7usize && numbers[1usize] == 8usize);
    assert!(numbers[2usize] == 9usize && numbers[3usize] == 10usize);
    let mut count_calls = 0usize;
    {
        let iterator = NonFused { calls: &mut count_calls };
        assert!(iterator.count() == 1usize);
    }
    assert!(count_calls == 2usize);
    let mut collect_calls = 0usize;
    let values: Vec<i64>;
    {
        let iterator = NonFused { calls: &mut collect_calls };
        values = iterator.collect();
    }
    assert!(collect_calls == 2usize);
    assert!(values.len() == 1usize && values[0usize] == 7i64);
    assert!(std::iter::range_from(!0usize).take(0usize).count() == 0usize);
}

pub trait IteratorExt<I: Iterator> {
    fn count(self) -> usize;
    fn collect(self) -> Vec<I::Item>;
    fn enumerate(self) -> Enumerate<I>;
    fn take(self, remaining: usize) -> Take<I>;
    fn skip(self, remaining: usize) -> Skip<I>;
    fn zip<J: IntoIterator>(self, right: J) -> Zip<I, J::IntoIter>;
    fn chain(self, right: I) -> Chain<I>;
    fn fold<B, F: FnMut(B, I::Item) -> B>(self, initial: B, function: F) -> B;
    fn for_each<F: FnMut(I::Item)>(self, function: F);
    fn map<B, F: FnMut(I::Item) -> B>(self, function: F) -> Map<I, F>;
    fn filter<F: FnMut(&I::Item) -> bool>(self, predicate: F) -> Filter<I, F>;
    fn filter_map<B, F: FnMut(I::Item) -> Option<B>>(self, function: F) -> FilterMap<I, F>;
    fn inspect<F: FnMut(&I::Item)>(self, function: F) -> Inspect<I, F>;
    fn any<F: FnMut(I::Item) -> bool>(&mut self, predicate: F) -> bool;
    fn all<F: FnMut(I::Item) -> bool>(&mut self, predicate: F) -> bool;
    fn find<F: FnMut(&I::Item) -> bool>(&mut self, predicate: F) -> Option<I::Item>;
    fn position<F: FnMut(I::Item) -> bool>(&mut self, predicate: F) -> Option<usize>;
}

impl<I: Iterator> IteratorExt<I> for I {
    fn count(self) -> usize {
        count(self)
    }
    fn collect(self) -> Vec<I::Item> {
        collect(self)
    }
    fn enumerate(self) -> Enumerate<I> {
        enumerate(self)
    }
    fn take(self, remaining: usize) -> Take<I> {
        take(self, remaining)
    }
    fn skip(self, remaining: usize) -> Skip<I> {
        skip(self, remaining)
    }
    fn zip<J: IntoIterator>(self, right: J) -> Zip<I, J::IntoIter> {
        zip(self, right)
    }
    fn chain(self, right: I) -> Chain<I> {
        chain(self, right)
    }
    fn fold<B, F: FnMut(B, I::Item) -> B>(self, initial: B, function: F) -> B {
        fold(self, initial, function)
    }
    fn for_each<F: FnMut(I::Item)>(self, function: F) {
        for_each(self, function)
    }
    fn map<B, F: FnMut(I::Item) -> B>(self, function: F) -> Map<I, F> {
        map(self, function)
    }
    fn filter<F: FnMut(&I::Item) -> bool>(self, predicate: F) -> Filter<I, F> {
        filter(self, predicate)
    }
    fn filter_map<B, F: FnMut(I::Item) -> Option<B>>(self, function: F) -> FilterMap<I, F> {
        filter_map(self, function)
    }
    fn inspect<F: FnMut(&I::Item)>(self, function: F) -> Inspect<I, F> {
        inspect(self, function)
    }
    fn any<F: FnMut(I::Item) -> bool>(&mut self, predicate: F) -> bool {
        any(self, predicate)
    }
    fn all<F: FnMut(I::Item) -> bool>(&mut self, predicate: F) -> bool {
        all(self, predicate)
    }
    fn find<F: FnMut(&I::Item) -> bool>(&mut self, predicate: F) -> Option<I::Item> {
        find(self, predicate)
    }
    fn position<F: FnMut(I::Item) -> bool>(&mut self, predicate: F) -> Option<usize> {
        position(self, predicate)
    }
}

/// Consume every item in order, dropping each before requesting the next.
pub fn count<I: Iterator>(mut iterator: I) -> usize {
    let mut total = 0usize;
    while let Some(value) = iterator.next() {
        total += 1usize;
        drop(value);
    }
    total
}

/// Collect into Vec; general FromIterator destinations are not provided.
pub fn collect<I: Iterator>(mut iterator: I) -> Vec<I::Item> {
    let mut values: Vec<I::Item> = Vec::new();
    while let Some(value) = iterator.next() {
        values.push(value);
    }
    values
}

/// An unbounded usize iterator; advancing beyond usize::MAX traps.
pub struct RangeFrom {
    next_value: usize,
}

pub fn range_from(start: usize) -> RangeFrom {
    RangeFrom { next_value: start }
}

impl Iterator for RangeFrom {
    type Item = usize;
    fn next(&mut self) -> Option<usize> {
        let value = self.next_value;
        self.next_value += 1usize;
        Some(value)
    }
}

impl IntoIterator for RangeFrom {
    type IntoIter = Self;
    fn into_iter(self) -> Self {
        self
    }
}

struct Mark {
    out: Stdout,
    byte: u8,
}

impl Drop for Mark {
    fn drop(&mut self) {
        self.out.write(&[self.byte]);
    }
}

struct Observed<'a> {
    calls: &'a mut usize,
    index: usize,
    end: usize,
}

impl<'a> Iterator for Observed<'a> {
    type Item = i64;
    fn next(&mut self) -> Option<i64> {
        *self.calls += 1usize;
        if self.index == self.end {
            return None;
        }
        let value = self.index as i64;
        self.index += 1usize;
        Some(value)
    }
}

fn scalar_cases() {
    assert!("".chars().count() == 0usize);
    assert!("a\u{e9}\u{65e5}\u{1f980}".chars().count() == 4usize);
    let empty: Vec<String> = Vec::new();
    assert!(empty.into_iter().count() == 0usize);
    let words = vec!["first".to_string(), "second".to_string()];
    assert!(std::iter::count(words.into_iter()) == 2usize);
    let mut calls = 0usize;
    {
        let iterator = Observed { calls: &mut calls, index: 0usize, end: 3usize };
        assert!(iterator.count() == 3usize);
    }
    assert!(calls == 4usize);
    let mut empty_calls = 0usize;
    {
        let iterator = Observed { calls: &mut empty_calls, index: 0usize, end: 0usize };
        assert!(iterator.count() == 0usize);
    }
    assert!(empty_calls == 1usize);
    let characters: Vec<char> = "a\u{e9}\u{65e5}\u{1f980}".chars().collect();
    assert!(characters.len() == 4usize);
    assert!(characters[0usize] == 'a');
    assert!(characters[1usize] == '\u{e9}');
    assert!(characters[2usize] == '\u{65e5}');
    assert!(characters[3usize] == '\u{1f980}');
    let empty_characters: Vec<char> = "".chars().collect();
    assert!(empty_characters.is_empty());
    let mut collected_calls = 0usize;
    let numbers: Vec<i64>;
    {
        let iterator = Observed { calls: &mut collected_calls, index: 0usize, end: 3usize };
        numbers = std::iter::collect(iterator);
    }
    assert!(collected_calls == 4usize);
    assert!(numbers.len() == 3usize);
    assert!(numbers[0usize] == 0i64 && numbers[1usize] == 1i64 && numbers[2usize] == 2i64);
    let words: Vec<String> = vec!["first".to_string(), "second".to_string()].into_iter().collect();
    assert!(words.len() == 2usize);
    assert!(words[0usize].as_str() == "first" && words[1usize].as_str() == "second");
    assert!(std::iter::range_from(9usize).take(0usize).count() == 0usize);
    let numbers: Vec<usize> = std::iter::range_from(7usize).take(4usize).collect();
    assert!(numbers.len() == 4usize);
    assert!(numbers[0usize] == 7usize && numbers[1usize] == 8usize);
    assert!(numbers[2usize] == 9usize && numbers[3usize] == 10usize);
